def mode(values):
    """Return the most common value in `values`. See PLAN.md task 2."""
    if not values:
        raise ValueError("values must not be empty")

    frequency = {}
    for value in values:
        if value in frequency:
            frequency[value] += 1
        else:
            frequency[value] = 1

    max_frequency = max(frequency.values())
    mode_value = min([value for value, freq in frequency.items() if freq == max_frequency])

    return mode_value

